import openpyxl
from openpyxl.cell.cell import Cell
inp = openpyxl.load_workbook('1_52964_answer_template_1190_input.xlsx')
gld = openpyxl.load_workbook('golden.xlsx')
wi=inp['Sheet1']; wg=gld['Sheet1']
diffs=[]
attrs=['number_format','font','border','fill','alignment','protection']
for r in range(1,280):
    for c in range(1,58):
        ci=wi.cell(r,c); cg=wg.cell(r,c)
        for a in attrs:
            ai=getattr(ci,a); ag=getattr(cg,a)
            # compare via repr of relevant public props
            def desc(x):
                if x is None: return None
                if a=='number_format': return x
                if a=='font':
                    return (x.name,x.sz,x.bold,x.italic,x.underline,x.strike,x.color.rgb if x.color else None,x.vertAlign)
                if a=='border':
                    return (x.left.style,x.right.style,x.top.style,x.bottom.style, x.diagonal.style)
                if a=='fill':
                    return (x.patternType, x.fgColor.rgb if x.fgColor else None, x.bgColor.rgb if x.bgColor else None)
                if a=='alignment':
                    return (x.horizontal,x.vertical,x.wrap_text,x.shrink_to_fit,x.text_rotation)
                if a=='protection':
                    return (x.locked,x.hidden)
            di=desc(ai); dg=desc(ag)
            if di!=dg:
                diffs.append((r,c,a,di,dg))
print('style diffs', len(diffs))
from collections import Counter
print(Counter(a for _,_,a,_,_ in diffs))
for d in diffs[:50]: print(d)
